window.docContents[125].resolve({"/9___-Structure-of-finite-dimensional-algebras/9___5___-Blocks/Blocks-of-semisimple___-local___-and-specific-algebras/#Chapter9___Example9___5___2":{"contents":"Example 9.5.2. If A is semisimple, each block is equivalent to the category of vector spaces (and thus has only one simple object). If A is a commutative local artinian algebra, then there is only one block. Also there is just one block for the algebra of Problem 9.3.2.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.5. Blocks\tBlocks of semisimple, local, and specific algebras","header":"Blocks of semisimple, local, and specific algebras","id":"/9___-Structure-of-finite-dimensional-algebras/9___5___-Blocks/Blocks-of-semisimple___-local___-and-specific-algebras/#Chapter9___Example9___5___2"}});
